import React, { useState } from "react";
import { Link } from "react-router-dom";
import { loginUser } from "../../api/authApi";

function Login(props) {
  const [form, setForm]       = useState({ name: "", password: "" });
  const [error, setError]     = useState("");
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const submitLogin = () => {
    setError("");
    setLoading(true);
    loginUser(form)
      .then((res) => {
        if (res.data && res.data.userId) {
          localStorage.setItem("tempUserId", res.data.userId);
          props.history.push("/verify-otp");
        }
        setLoading(false);
      })
      .catch(() => {
        setError("Invalid credentials. Please check your username and password.");
        setLoading(false);
      });
  };

  const handleKeyDown = (e) => { if (e.key === "Enter") submitLogin(); };

  return (
    <div className="d-flex align-items-center justify-content-center min-vh-100 bg-info bg-opacity-10">
      <div className="card shadow-sm border-0" style={{ maxWidth: "400px", width: "100%" }}>
        <div className="card-body p-4 p-md-5">

          <div className="text-center mb-4">
            <div className="d-inline-flex align-items-center justify-content-center bg-primary rounded-circle mb-2"
                 style={{ width: "56px", height: "56px", fontSize: "26px" }}>
              🏦
            </div>
            <h4 className="fw-bold mb-1">FinGenie Bank</h4>
            <p className="text-muted small mb-0">Sign in to access your account</p>
          </div>

          {error && (
            <div className="alert alert-danger py-2 small" role="alert">
              {error}
            </div>
          )}

          <div className="mb-3">
            <label className="form-label small fw-semibold">Username</label>
            <input
              name="name"
              type="text"
              className="form-control"
              placeholder="Enter your username"
              value={form.name}
              onChange={handleChange}
              onKeyDown={handleKeyDown}
            />
          </div>

          <div className="mb-4">
            <label className="form-label small fw-semibold">Password</label>
            <input
              name="password"
              type="password"
              className="form-control"
              placeholder="Enter your password"
              value={form.password}
              onChange={handleChange}
              onKeyDown={handleKeyDown}
            />
          </div>

          <button
            className="btn btn-primary w-100 d-flex align-items-center justify-content-center gap-2"
            onClick={submitLogin}
            disabled={loading}
          >
            {loading ? (
              <>
                <span className="spinner-border spinner-border-sm" role="status"></span>
                Signing in…
              </>
            ) : (
              "Sign In"
            )}
          </button>

          <p className="text-center small text-muted mt-4 mb-0">
            Don't have an account? <Link to="/register">Create one</Link>
          </p>

        </div>
      </div>
    </div>
  );
}

export default Login;
